const inner = $input.first().json;
const textPart = inner.content && inner.content[0] ? inner.content[0].text : (inner.text || inner.output || '');
const jsonMatch = String(textPart).match(/\{[\s\S]*\}/);
let terms = {};
if (jsonMatch) { terms = JSON.parse(jsonMatch[0]); }

// The Code node sandbox does not expose the `crypto` global -- crypto.randomUUID()
// throws ReferenceError. Self-contained UUID v4 instead.
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
  const r = Math.random() * 16 | 0;
  const v = c === 'x' ? r : ((r & 0x3) | 0x8);
  return v.toString(16);
});

const intake = $('Normalize Submission').first().json;
const q = (v) => (v === null || v === undefined) ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const num = (v) => (v === null || v === undefined || v === '') ? 'NULL' : String(Number(v));

// INDUSTRY RESOLUTION -- do not simplify this.
// The n8n Form dropdown submits the human LABEL ('Events & Hospitality'), while the
// webhook path submits the CODE ('EVENTS'). An earlier version only uppercased the
// value, so every label failed the enum check and fell back to EVENTS -- meaning
// manufacturing, healthcare and prof-services attendees would all have seen an
// events onboarding. That silently destroys the industry-adaptive premise, which is
// the whole reason the demo satisfies 'relatable to many industries'.
const LABEL_TO_CODE = {
  'EVENTS & HOSPITALITY': 'EVENTS',
  'EVENTS AND HOSPITALITY': 'EVENTS',
  'EVENTS': 'EVENTS',
  'MANUFACTURING': 'MANUFACTURING',
  'HEALTHCARE': 'HEALTHCARE',
  'HEALTH CARE': 'HEALTHCARE',
  'PROFESSIONAL SERVICES': 'PROF_SERVICES',
  'PROF_SERVICES': 'PROF_SERVICES'
};
const rawIndustry = String(intake.industry || '').trim().toUpperCase();
const industry = LABEL_TO_CODE[rawIndustry] || 'EVENTS';

const clientName = terms.client_name || intake.company;

// The vocabulary shift. A healthcare executive must never see the word 'Event'.
const NOUN = { EVENTS: 'Event', MANUFACTURING: 'Supplier', HEALTHCARE: 'Provider', PROF_SERVICES: 'Engagement' };
const SUFFIX = { EVENTS: 'Annual Leadership Summit', MANUFACTURING: 'Tier 1 Supplier Qualification', HEALTHCARE: 'Provider Credentialing Cohort', PROF_SERVICES: 'FY27 Advisory Engagement' };
const industryNoun = NOUN[industry];
const engagementName = clientName + ' - ' + SUFFIX[industry];

const clientId = uuid();
const engagementId = uuid();
const leadId = uuid();

const TASKS = {
  EVENTS: ['Confirm shuttle vendor', 'Lock venue contract', 'Finalize catering headcount', 'Schedule AV load-in', 'Issue deposit invoice'],
  MANUFACTURING: ['Request quality certifications', 'Schedule supplier audit', 'Create ERP vendor record', 'Issue first purchase order', 'Confirm logistics lane'],
  HEALTHCARE: ['Collect provider credentials', 'Submit primary source verification', 'File payer enrollment', 'Provision EMR access', 'Confirm privileging'],
  PROF_SERVICES: ['Run conflict check', 'Issue engagement letter', 'Open matter in billing', 'Assign engagement team', 'Set rate card']
};
const PRIMARY = { EVENTS: 'SHUTTLE', MANUFACTURING: 'QUALITY_AUDIT', HEALTHCARE: 'CREDENTIALING', PROF_SERVICES: 'CONFLICT_CHECK' };

const sqlClients = 'INSERT INTO AIGS_DEMO.ONBOARDING.CLIENTS (client_id, client_name, industry, contact_name, contact_email, source, created_at) VALUES ('
  + [q(clientId), q(clientName), q(industry), q(intake.full_name), q(intake.email), q('DEMO_LIVE'), 'CURRENT_TIMESTAMP()'].join(', ') + ')';

const signed = terms.contract_signed_at ? q(terms.contract_signed_at) : 'CURRENT_TIMESTAMP()';
const goLive = terms.go_live_date ? q(terms.go_live_date) : 'NULL';
const sqlEngagements = 'INSERT INTO AIGS_DEMO.ONBOARDING.ENGAGEMENTS (engagement_id, client_id, industry, engagement_name, contract_value, contract_signed_at, go_live_date, status, onboarding_started_at, budget_variance, risk_flag) VALUES ('
  + [q(engagementId), q(clientId), q(industry), q(engagementName), num(terms.contract_value), signed, goLive, q('IN_PROGRESS'), 'CURRENT_TIMESTAMP()', '0', 'FALSE'].join(', ') + ')';

const taskList = TASKS[industry];
const tuples = taskList.map(function (name, i) {
  return '(' + [q(uuid()), q(engagementId), q(name), q(industry), String(i + 1), q(intake.full_name), 'DATEADD(day, ' + ((i + 1) * 2) + ', CURRENT_DATE())', q('PENDING')].join(', ') + ')';
});
const sqlTasks = 'INSERT INTO AIGS_DEMO.ONBOARDING.TASKS (task_id, engagement_id, task_name, task_category, sequence, assigned_to, due_date, status) SELECT column1, column2, column3, column4, column5, column6, column7, column8 FROM VALUES ' + tuples.join(', ');

const svc = PRIMARY[industry];
const sqlBookings = 'INSERT INTO AIGS_DEMO.ONBOARDING.VENDOR_BOOKINGS (booking_id, engagement_id, vendor_id, service_type, booked_at, status, cost) SELECT '
  + [q(uuid()), q(engagementId), 'v.vendor_id', q(svc), 'CURRENT_TIMESTAMP()', q('CONFIRMED'), 'v.cost_per_unit'].join(', ')
  + ' FROM AIGS_DEMO.ONBOARDING.VENDORS v WHERE v.industry = ' + q(industry) + ' AND v.service_type = ' + q(svc)
  + ' AND v.active = TRUE ORDER BY v.rating DESC, v.cost_per_unit ASC LIMIT 1';

const sqlLeads = 'INSERT INTO AIGS_DEMO.ONBOARDING.ATTENDEE_LEADS (lead_id, submitted_at, full_name, email, company, job_title, industry, self_reported_days, engagement_id, enrichment_status) VALUES ('
  + [q(leadId), 'CURRENT_TIMESTAMP()', q(intake.full_name), q(intake.email), q(intake.company), q(intake.job_title), q(industry), num(intake.self_reported_days), q(engagementId), q('PENDING')].join(', ') + ')';

return [{ json: {
  engagement_id: engagementId,
  client_id: clientId,
  lead_id: leadId,
  industry: industry,
  industry_noun: industryNoun,
  industry_raw: rawIndustry,
  client_name: clientName,
  engagement_name: engagementName,
  contract_value: terms.contract_value === undefined ? null : terms.contract_value,
  go_live_date: terms.go_live_date === undefined ? null : terms.go_live_date,
  self_reported_days: intake.self_reported_days,
  task_count: taskList.length,
  sql_clients: sqlClients,
  sql_engagements: sqlEngagements,
  sql_tasks: sqlTasks,
  sql_bookings: sqlBookings,
  sql_leads: sqlLeads
} }];

options.customCss:
@import url('https://fonts.googleapis.com/css2?family=Bai+Jamjuree:wght@600;700&family=Outfit:wght@400;500&display=swap');

:root {
  --brand-orange: #FF9240;
  --brand-blue: #3898EC;
  --brand-navy: #2D4979;
  --text: #0D0D0D;
}

body, .container {
  font-family: 'Outfit', -apple-system, system-ui, sans-serif;
  color: var(--text);
  background: #FFFFFF;
}

h1, .form-header h1 {
  font-family: 'Bai Jamjuree', 'Outfit', sans-serif;
  font-weight: 700;
  color: var(--brand-navy);
  letter-spacing: -0.02em;
}

.form-header p, .form-description {
  font-family: 'Outfit', sans-serif;
  font-size: 17px;
  line-height: 1.5;
}

label, .form-label {
  font-family: 'Outfit', sans-serif;
  font-weight: 500;
  color: var(--brand-navy);
}

input, select, textarea {
  font-family: 'Outfit', sans-serif;
  font-size: 17px;
  border-radius: 10px;
  border: 1.5px solid #D8DEE9;
}

input:focus, select:focus, textarea:focus {
  border-color: var(--brand-blue);
  outline: none;
  box-shadow: 0 0 0 3px rgba(56,152,236,0.15);
}

button[type='submit'], .btn-primary {
  background: var(--brand-orange);
  border-color: var(--brand-orange);
  color: #FFFFFF;
  font-family: 'Bai Jamjuree', sans-serif;
  font-weight: 600;
  font-size: 18px;
  border-radius: 10px;
  padding: 14px 24px;
}

button[type='submit']:hover, .btn-primary:hover {
  background: #F07E28;
  border-color: #F07E28;
}

.card, .form-container {
  border-radius: 10px;
}

